### 2. FastAPI Integration with Bulk Indexing

From your prior sessions, you used bulk indexing to handle 1,200 events with 98% accuracy. Here's a production-ready FastAPI endpoint using **async bulk indexing** and a **background queue**:

```python
from fastapi import FastAPI, HTTPException, BackgroundTasks
from pydantic import BaseModel, validator
from elasticsearch import Elasticsearch, helpers
from queue import Queue
from threading import Thread
import logging
import datetime

app = FastAPI()
es = Elasticsearch([{'host': 'localhost', 'port': 9200}])

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Async buffer queue
event_queue = Queue(maxsize=5000)

class Event(BaseModel):
    event_time: str
    agent_id: int
    event_type: str
    details: str

    @validator('agent_id')
    def validate_agent_id(cls, v):
        if v is None or v <= 0:
            raise ValueError("agent_id must be a positive integer")
        return v

def bulk_indexer():
    """Background thread that batches and indexes events."""
    while True:
        batch = []
        while len(batch) < 500 and not event_queue.empty():
            batch.append(event_queue.get())

        if batch:
            actions = [
                {"_index": "events", "_source": event}
                for event in batch
            ]
            try:
                success, failed = helpers.bulk(es, actions)
                logger.info(f"Indexed {success} events, {failed} failed")
            except Exception as e:
                logger.error(f"Bulk indexing error: {e}")

# Start background indexer thread
Thread(target=bulk_indexer, daemon=True).start()

@app.post("/log/event")
async def log_event(event: Event):
    try:
        event_queue.put_nowait(event.dict())
        return {"status": "queued"}
    except Exception:
        raise HTTPException(status_code=503, detail="Event queue is full")
```

